const doctor_id = Number($json.doctor_id);
const appointment_date = String($json.appointment_date || "").trim();

if (!doctor_id || !appointment_date) {
  return [
    {
      json: {
        valid: false,
        error: "doctor_id and appointment_date are required."
      }
    }
  ];
}

const match = appointment_date.match(/^(\d{4})-(\d{2})-(\d{2})$/);

if (!match) {
  return [
    {
      json: {
        valid: false,
        error: "Invalid appointment_date format. Use YYYY-MM-DD."
      }
    }
  ];
}

const [_, year, month, day] = match.map(Number);

// Use UTC to avoid timezone shifting issue
const date = new Date(Date.UTC(year, month - 1, day));

const days = [
  "sunday",
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday"
];

const day_of_week = days[date.getUTCDay()];

return [
  {
    json: {
      valid: true,
      doctor_id,
      appointment_date,
      day_of_week
    }
  }
];

const doctor = $("Get Doctor Details").first().json;

// Booked appointments come from Get Booked Appointments
const bookedAppointments = $("Get Booked Appointments").all().map(item => item.json);

// Doctor unavailable slots come from Get Doctor Unavailability
const unavailableRows = $("Get Doctor Unavailability").all().map(item => item.json);

const slotInput = $("Prepare Slot Request Input").first().json;
const appointment_date = slotInput.appointment_date;

if (!doctor || !doctor.doctor_id) {
  return [
    {
      json: {
        available: false,
        doctor_id: slotInput.doctor_id,
        appointment_date,
        slots: [],
        message: "Doctor not found or inactive."
      }
    }
  ];
}

if (!doctor.day_of_week || doctor.is_available === 0 || doctor.is_available === false) {
  return [
    {
      json: {
        available: false,
        doctor_id: doctor.doctor_id,
        doctor_name: doctor.doctor_name,
        department: doctor.department,
        appointment_date,
        slots: [],
        message: `${doctor.doctor_name} is not available on this date.`
      }
    }
  ];
}

function toMinutes(time) {
  const [h, m] = String(time).slice(0, 5).split(":").map(Number);
  return h * 60 + m;
}

function toTimeString(minutes) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:00`;
}

function toAmPm(time) {
  const [h, m] = String(time).slice(0, 5).split(":").map(Number);
  const suffix = h >= 12 ? "PM" : "AM";
  const hour12 = h % 12 || 12;
  return `${hour12}:${String(m).padStart(2, "0")} ${suffix}`;
}

function getIndiaDateTimeParts() {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Kolkata",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  }).formatToParts(new Date());

  const data = {};
  for (const part of parts) {
    data[part.type] = part.value;
  }

  return {
    today: `${data.year}-${data.month}-${data.day}`,
    currentMinutes: Number(data.hour) * 60 + Number(data.minute)
  };
}

const startTime = doctor.start_time || doctor.available_from;
const endTime = doctor.end_time || doctor.available_to;
const duration = Number(doctor.consultation_duration || 30);

const booked = bookedAppointments
  .filter(a => a.booked_start && a.booked_end)
  .map(a => ({
    start: String(a.booked_start).slice(0, 8),
    end: String(a.booked_end).slice(0, 8)
  }));

const unavailable = unavailableRows
  .filter(u => u.start_time && u.end_time)
  .map(u => ({
    start: String(u.start_time).slice(0, 8),
    end: String(u.end_time).slice(0, 8),
    reason: u.reason || "Doctor unavailable"
  }));

const indiaNow = getIndiaDateTimeParts();

const availableSlots = [];

let current = toMinutes(startTime);
const end = toMinutes(endTime);

while (current + duration <= end) {
  const slotStart = toTimeString(current);
  const slotEnd = toTimeString(current + duration);

  const isBooked = booked.some(b => {
    return slotStart < b.end && slotEnd > b.start;
  });

  const isUnavailable = unavailable.some(u => {
    return slotStart < u.end && slotEnd > u.start;
  });

  const isPastTodaySlot =
    appointment_date === indiaNow.today &&
    current < indiaNow.currentMinutes + 10;

  if (!isBooked && !isUnavailable && !isPastTodaySlot) {
    availableSlots.push({
      start_time: slotStart,
      end_time: slotEnd,
      display_time: toAmPm(slotStart)
    });
  }

  current += duration;
}

let message = "";

if (availableSlots.length > 0) {
  message = `Available slots found for ${doctor.doctor_name}.`;
} else if (unavailable.length > 0) {
  message = `${doctor.doctor_name} has no available slots on this date due to unavailability.`;
} else {
  message = `No available slots found for ${doctor.doctor_name} on this date.`;
}

return [
  {
    json: {
      available: availableSlots.length > 0,
      doctor_id: doctor.doctor_id,
      doctor_name: doctor.doctor_name,
      department: doctor.department,
      specialization: doctor.specialization,
      appointment_date,
      consultation_duration: duration,
      available_from: startTime,
      available_to: endTime,
      unavailable_periods: unavailable,
      total_slots: availableSlots.length,
      slots: availableSlots,
      message
    }
  }
];
